mockup.css:
.mock-section-two-column-prose { background: #fbf9f3; color: #191712; font-family: var(--f-serif);
  padding: 6cqw 7cqw; display: flex; flex-direction: column; gap: 3.4cqw; }
.mock-section-two-column-prose h4 { margin: 0; font-size: 4.2cqw; line-height: 1.06; letter-spacing: -.02em; max-width: 20ch; }
.mock-section-two-column-prose .cols { column-count: 2; column-gap: 5cqw; font-size: 1.7cqw; line-height: 1.62; }
.mock-section-two-column-prose .cols p { margin: 0 0 1.5cqw; }
.mock-section-two-column-prose .sig { font-family: var(--f-sans); font-size: 1.2cqw; letter-spacing: .16em;
  text-transform: uppercase; opacity: .45; }
